    v: [['考究', 'kǎojiū', 'khảo cứu'], ['字源', 'zìyuán', 'nguồn gốc chữ'], ['工具书', 'gōngjùshū', 'sách công cụ'], ['杰作', 'jiézuò', 'kiệt tác'], ['古籍', 'gǔjí', 'sách cổ'], ['编排', 'biānpái', 'sắp xếp'], ['失落', 'shīluò', 'thất lạc'], ['注释', 'zhùshì', 'chú thích']],
