    { t: 'order', q: '根据文章内容排序。', items: [['特殊的讲解人和特殊的观众', '大伟为盲人创办影院的起因', '“心目影院”开办初期情况', '大伟为了提高讲解水平付出各种努力', '盲人电影院的发展', '盲人对“心目影院”的评价', '大伟感受到的欣慰和快乐']] }
