    an: [['尤其要感谢那些上不好课的教授，因为他们使你不得不自学。', 'Hài hước nghịch lý: cảm ơn thầy dạy dở vì buộc ta tự học; 不得不 = buộc phải.', 'Đặc biệt phải cảm ơn những giáo sư dạy không hay, vì họ buộc bạn phải tự học.'], ['我的一生中，得到的多于我付出的，所以我要回报社会。', '“得到的/付出的” — cấu trúc 的 danh từ hoá; “多于” = nhiều hơn.', 'Cả đời tôi nhận được nhiều hơn những gì đã cho đi, nên tôi muốn đền đáp xã hội.']],
    v: [['毕业典礼', 'bìyè diǎnlǐ', 'lễ tốt nghiệp'], ['闲谈', 'xiántán', 'chuyện phiếm'], ['谈判', 'tánpàn', 'đàm phán'], ['罢休', 'bàxiū', 'thôi, bỏ qua'], ['短暂', 'duǎnzàn', 'ngắn ngủi'], ['白发苍苍', 'báifà-cāngcāng', 'tóc bạc phơ'], ['自豪', 'zìháo', 'tự hào'], ['志向', 'zhìxiàng', 'chí hướng'], ['发扬', 'fāyáng', 'phát huy']],
